import { Injectable, NgZone } from '@angular/core';
import { from, Observable, of, throwError } from 'rxjs';
import { catchError, map, tap } from 'rxjs/operators';

import {
  clarificationOptionSelectionSchema,
  clarificationPromptRequestSchema,
  clarificationPromptResponseSchema
} from '@clarityokr/contracts';

import { ClarificationStore } from '../state/clarification.store';
import { IPC_CHANNELS } from '../../shared/ipc-channel.tokens';

@Injectable({ providedIn: 'root' })
export class ClarificationOrchestratorService {
  private readonly bridge = typeof window !== 'undefined' ? window.clarifyOkr : undefined;
  private isListenerRegistered = false;

  constructor(private readonly store: ClarificationStore, private readonly zone: NgZone) {
    this.registerPromptListener();
  }

  requestPrompt(sessionId: string, intent: string): Observable<void> {
    if (!this.bridge) {
      return throwError(() => new Error('ClarifyOKR bridge is unavailable.'));
    }

    const payload = clarificationPromptRequestSchema.parse({ sessionId, intent });

    return from(this.bridge.invoke(IPC_CHANNELS.CLARIFICATION_PROMPT, payload)).pipe(
      map((response) => clarificationPromptResponseSchema.parse(response)),
      tap(({ prompt }) => this.store.setPrompt(prompt)),
      map(() => void 0),
      catchError((error) => {
        this.store.setValidationError(error instanceof Error ? error.message : String(error));
        return throwError(() => error);
      })
    );
  }

  recordSelection(sessionId: string, promptId: string, optionId: string): Observable<void> {
    if (!this.bridge) {
      return throwError(() => new Error('ClarifyOKR bridge is unavailable.'));
    }

    this.store.recordSelection(optionId);

    const payload = clarificationOptionSelectionSchema.parse({ sessionId, promptId, optionId });
    this.bridge.send(IPC_CHANNELS.CLARIFICATION_RESPOND, payload);

    return of(void 0);
  }

  markReady(ready: boolean): void {
    this.store.markReady(ready);
  }

  private registerPromptListener(): void {
    if (!this.bridge || this.isListenerRegistered) {
      return;
    }

    this.bridge.on(IPC_CHANNELS.CLARIFICATION_PROMPT, (_event, payload) => {
      this.zone.run(() => {
        try {
          const { prompt } = clarificationPromptResponseSchema.parse(payload);
          this.store.setPrompt(prompt);
        } catch (error) {
          this.store.setValidationError(error instanceof Error ? error.message : String(error));
        }
      });
    });

    this.isListenerRegistered = true;
  }
}
