    this.orchestrator
      .recordSelection(this.sessionId, this.latestPrompt.id, optionId)
      .subscribe({
        error: (error) => {
          this.statusMessage = error instanceof Error ? error.message : String(error);
        }
      });
  }

  onGenerate(): void {
    if (!this.sessionId) {
      return;
    }

    this.generatedSummary = `OKR ready for "${this.intentControl.value}"`;
    this.statusMessage = '';
    this.isClarifying = false;
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }
