    const el = document.querySelector('[data-testid="prompt-question"]');
    return !!el && el.textContent?.includes('再补充');
  });
  await optionLocator.last().click();

  const generateButton = mainWindow.locator('[data-testid="clarification-generate"]');
  await expect(generateButton).toBeEnabled();
  await generateButton.click();
}

test('sticky window stays always-on-top with OKR contents rendered', async () => {
  const electronApp = await electron.launch({ args: ['.'], cwd: ROOT });
  const mainWindow = await electronApp.firstWindow();

  await completeClarification(mainWindow);

  const stickyWindow = await electronApp.waitForEvent('window', {
    predicate: (window) => window !== mainWindow
  });
  await stickyWindow.waitForSelector('[data-testid="sticky-objective"]');

  const isAlwaysOnTop = await electronApp.evaluate(({ BrowserWindow }) => {
    const win = BrowserWindow.getAllWindows().find(
      (candidate) => candidate.getTitle() === 'ClarityOKR Sticky'
    );
